 "content": "from collections import deque

def _components(g):
    h, w = len(g), len(g[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            a=[row[c0:c1+1] for row in g[r0:r1+1]]
            comps.append((len(cells),r0,c0,a))
    return sorted(comps, reverse=True, key=lambda z:z[0])

def transform(grid):
    comps = _components(grid)
    if len(comps) < 2:
        return [[8]]
    # Compare the two dominant repeated designs under translation; maximize
    # exact pixel agreement over their common rectangular footprint.
    _, ar, ac, A = comps[0]
    _, br, bc, B = comps[1]
    best = None
    for dy in range(-len(B)+1, len(A)):
        for dx in range(-len(B[0])+1, len(A[0])):
            ay0=max(0,dy); by0=max(0,-dy)
            ax0=max(0,dx); bx0=max(0,-dx)
            hh=min(len(A)-ay0,len(B)-by0)
            ww=min(len(A[0])-ax0,len(B[0])-bx0)
            if hh<=0 or ww<=0: continue
            eq=mis=nonzero=0
            for y in range(hh):
                for x in range(ww):
                    u=A[ay0+y][ax0+x]; v=B[by0+y][bx0+x]
                    if u==v: eq+=1
                    else: mis+=1
                    if u or v: nonzero+=1
            # Prefer broad overlap and agreement, while allowing the encoded
            # defects to be the small set of unequal cells.
            score=(eq, nonzero, hh*ww, -mis)
            if best is None or score>best[0]:
                best=(score, ay0,by0,ax0,bx0,hh,ww)
    _,ay0,by0,ax0,bx0,hh,ww=best
    diffs=[]
    for y in range(hh):
        for x in range(ww):
            if A[ay0+y][ax0+x] != B[by0+y][bx0+x]:
                diffs.append((y,x))
    if not diffs:
        return [[0]]
    y0=min(y for y,x in diffs); y1=max(y for y,x in diffs)
    x0=min(x for y,x in diffs); x1=max(x for y,x in diffs)
    return [[8 if A[ay0+y][ax0+x] != B[by0+y][bx0+x] else 0
             for x in range(x0,x1+1)] for y in range(y0,y1+1)]
"
}

